//! Upper bounds of message lengths, from the [MaxSize] of what they carry (SW-19, the first step of API-18).
//!
//! Server code generated by `ww_codegen!` has a `<METHOD>_REQUEST_MAX_LEN` and a `<METHOD>_RESPONSE_MAX_LEN`
//! const for each method, made with these functions from the `MAX_SIZE` of its arguments and of its return type:
//! `Some` when all of them are bounded (see `shrink_wrap::MaxLen`), `None` otherwise.

use wire_weaver::shrink_wrap::{MaxSize, UNib32};
use wire_weaver::ww_version::CompactVersion;

/// Worst-case length of a [Request](crate::Request) calling the method at the absolute `path` (array indices
/// included, `u32::MAX` for an index that can be anything), `args` the `MAX_SIZE` of its arguments struct
/// (`Some(MaxSize::ZERO)` without arguments). Also of a property or sink write, `args` the value's `MAX_SIZE`.
///
/// Only absolute paths: a `GlobalFull` path carries version strings and has no bound, a `GlobalCompact` one is
/// [call_request_compact].
pub const fn call_request(path: &[u32], args: Option<MaxSize>) -> Option<usize> {
    request(path_nibbles(path), path.len(), args)
}

/// [call_request] with a `GlobalCompact` path: `path_from_trait` from the trait root.
pub const fn call_request_compact(path_from_trait: &[u32], args: Option<MaxSize>) -> Option<usize> {
    let path = MaxSize::seq(
        MaxSize::of_write::<CompactVersion>(),
        Some(path_nibbles(path_from_trait)),
    );
    let Some(path) = path else {
        return None;
    };
    request(path, path_from_trait.len(), args)
}

/// Worst-case length of the [Event](crate::Event) answering a method call with its value, `output` the `MAX_SIZE`
/// of the return type (`Some(MaxSize::ZERO)` for none). Also of a property read.
pub const fn value_event(output: Option<MaxSize>) -> Option<usize> {
    let Some(output) = output else {
        return None;
    };
    // seq (UVlq32), result flag, EventKind discriminant
    let head = MaxSize::seq(
        Some(MaxSize::bytes(5)),
        MaxSize::seq(Some(MaxSize::bits(1)), Some(MaxSize::nibbles(1))),
    );
    // the value written in place (a handler's answer), or as bytes after it (a deferred answer)
    let in_place = Some(output);
    let as_bytes = Some(MaxSize::bytes(output.buffer_len()));
    MaxSize::buffer_len_of(MaxSize::seq(head, MaxSize::one_of(in_place, as_bytes)))
}

/// Path elements as `UNib32`s.
const fn path_nibbles(path: &[u32]) -> MaxSize {
    let mut nibbles = 0;
    let mut i = 0;
    while i < path.len() {
        nibbles += UNib32(path[i]).len_nibbles();
        i += 1;
    }
    MaxSize::nibbles(nibbles)
}

/// `seq`, a `PathKind` with `path` of `path_len` elements, `RequestKind::Call` with `args` as bytes.
const fn request(path: MaxSize, path_len: usize, args: Option<MaxSize>) -> Option<usize> {
    let Some(args) = args else {
        return None;
    };
    // UVlq32Backfill, PathKind discriminant, path length and elements
    let size = MaxSize::seq(Some(MaxSize::bytes(5)), Some(MaxSize::nibbles(1)));
    let size = MaxSize::seq(size, Some(MaxSize::len_slot(path_len)));
    let size = MaxSize::seq(size, Some(path));
    // RequestKind discriminant, the arguments serialized on their own
    let size = MaxSize::seq(size, Some(MaxSize::nibbles(1)));
    let size = MaxSize::seq(size, Some(MaxSize::bytes(args.buffer_len())));
    MaxSize::buffer_len_of(size)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::builder::{EventBuilder, EventKindBuilder};
    use crate::{Event, EventKind, PathKind, Request, RequestKind};
    use wire_weaver::prelude::*;
    use wire_weaver::shrink_wrap::tail_bytes::TailBytes;
    use wire_weaver::shrink_wrap::{UVlq32, UVlq32Backfill};

    #[derive_shrink_wrap(borrowed)]
    struct Args<'i> {
        offset: u32,
        last: bool,
        data: MaxLen<RefVec<'i, u8>, 200>,
        name: MaxLen<&'i str, 9>,
    }

    fn args_bytes(buf: &mut [u8]) -> &[u8] {
        let data = [0xAA; 200];
        let args = Args {
            offset: u32::MAX,
            last: true,
            data: MaxLen::new(RefVec::new_bytes(&data)).unwrap(),
            name: MaxLen::new("123456789").unwrap(),
        };
        args.to_ww_bytes(buf).unwrap()
    }

    const ARGS_MAX: Option<MaxSize> = <Args<'static> as SerializeShrinkWrap>::MAX_SIZE;

    #[test]
    fn call_request_fits() {
        let mut args_buf = [0u8; 512];
        let args = args_bytes(&mut args_buf);
        for path in [&[0u32][..], &[3, u32::MAX, 7], &[1000, 0, 0, 0, 0]] {
            let max = call_request(path, ARGS_MAX).unwrap();
            let path_elements: Vec<UNib32> = path.iter().map(|p| UNib32(*p)).collect();
            let request = Request {
                seq: UVlq32Backfill(u32::MAX),
                priority: crate::Priority::NORMAL.nibble(),
                path_kind: PathKind::Absolute {
                    path: RefVec::Slice {
                        slice: &path_elements,
                    },
                },
                kind: RequestKind::Call {
                    args: TailBytes(args),
                },
            };
            let mut buf = vec![0u8; max];
            let len = request.to_ww_bytes(&mut buf).unwrap().len();
            assert!(len <= max && max <= len + 4, "{len} vs {max}");

            let max = call_request_compact(path, ARGS_MAX).unwrap();
            let request = Request {
                seq: UVlq32Backfill(u32::MAX),
                priority: crate::Priority::NORMAL.nibble(),
                path_kind: PathKind::GlobalCompact {
                    gid: CompactVersion {
                        gid: ww_global::GlobalTypeId::new(u32::MAX),
                        major: UNib32(u32::MAX),
                        minor: UNib32(u32::MAX),
                        patch: UNib32(u32::MAX),
                    },
                    path_from_trait: RefVec::Slice {
                        slice: &path_elements,
                    },
                },
                kind: RequestKind::Call {
                    args: TailBytes(args),
                },
            };
            let mut buf = vec![0u8; max];
            let len = request.to_ww_bytes(&mut buf).unwrap().len();
            assert!(len <= max && max <= len + 4, "{len} vs {max}");
        }
        assert_eq!(call_request(&[0], None), None);
        // 7 bytes, the path length counted as a u16 slot
        assert_eq!(call_request(&[0], Some(MaxSize::ZERO)), Some(9));
    }

    #[test]
    fn value_event_fits() {
        let max = value_event(ARGS_MAX).unwrap();

        // written in place by a handler's answer
        let mut buf = vec![0u8; max];
        let mut wr = BufWriter::new(&mut buf);
        let event_builder = EventBuilder::new(u32::MAX, &mut wr).unwrap();
        let event_kind_builder = EventKindBuilder::new(&mut wr).unwrap();
        let data = [0xAA; 200];
        Args {
            offset: u32::MAX,
            last: true,
            data: MaxLen::new(RefVec::new_bytes(&data)).unwrap(),
            name: MaxLen::new("123456789").unwrap(),
        }
        .ser_shrink_wrap(&mut wr)
        .unwrap();
        event_kind_builder.finish_with_kind(crate::EventKindDiscriminants::Value, &mut wr);
        event_builder.finish(true, &mut wr);
        let len = wr.finish().unwrap().len();
        // the lengths counted as u16 slots, and once more for the deferred answer's bytes
        assert!(len <= max && max <= len + 8, "{len} vs {max}");

        // as bytes, by a deferred answer
        let mut args_buf = [0u8; 512];
        let output = args_bytes(&mut args_buf);
        let event = Event {
            seq: UVlq32(u32::MAX),
            result: Ok(EventKind::Value {
                data: TailBytes(output),
            }),
        };
        let mut buf = vec![0u8; max];
        let len = event.to_ww_bytes(&mut buf).unwrap().len();
        assert!(len <= max, "{len} vs {max}");
    }
}
